<?php
namespace App\Http\Controllers;
use App\Core\Request;use App\Core\Response;use App\Core\Session;use App\Core\View;use PDO;
final class AdminTaskController{
 public function __construct(private string $root,private PDO $db){}
 public function index():void{$rows=$this->db->query('SELECT * FROM task_templates ORDER BY updated_at DESC,title')->fetchAll();View::render($this->root,'admin/tasks',['pageTitle'=>'Aufgabenbibliothek','templates'=>$rows]);}
 public function save(Request $r):void{$id=(int)$r->input('id');$title=trim((string)$r->input('title'));$fields=json_decode((string)$r->input('fields_json','[]'),true);if($title===''||!is_array($fields)){Session::flash('error','Titel und gültiges Felder-JSON sind erforderlich.');Response::redirect('/admin/aufgaben');}$photos=json_decode((string)$r->input('photos_json','[]'),true);$violation=json_decode((string)$r->input('violation_json','{}'),true);if($id)$this->db->prepare('UPDATE task_templates SET title=?,description=?,fields_json=?,photos_json=?,deadline_minutes=?,compensation=?,violation_json=?,is_active=?,updated_at=NOW() WHERE id=?')->execute([$title,trim((string)$r->input('description')),json_encode($fields,JSON_UNESCAPED_UNICODE),json_encode($photos,JSON_UNESCAPED_UNICODE),(int)$r->input('deadline_minutes'),(float)$r->input('compensation'),json_encode($violation,JSON_UNESCAPED_UNICODE),(int)!!$r->input('is_active'),$id]);else $this->db->prepare('INSERT INTO task_templates(title,description,fields_json,photos_json,deadline_minutes,compensation,violation_json,is_active,created_at,updated_at) VALUES(?,?,?,?,?,?,?,1,NOW(),NOW())')->execute([$title,trim((string)$r->input('description')),json_encode($fields,JSON_UNESCAPED_UNICODE),json_encode($photos,JSON_UNESCAPED_UNICODE),(int)$r->input('deadline_minutes'),(float)$r->input('compensation'),json_encode($violation,JSON_UNESCAPED_UNICODE)]);Session::flash('success','Aufgabenvorlage gespeichert.');Response::redirect('/admin/aufgaben');}
}